      Register.Alias(gargoyle, "statue gargoyle");

      // renamed uniques.
      Register.Alias(Deliarne, "Dark One");
      Register.Alias(Huhetotl, "Minion of Huhetotl");
      Register.Alias(Neferet, "Neferet the Green");
      Register.Alias(Kaloi_Thrym, "Dark Lord");
